-- A20 — situação interna de inventário; não representa disponibilidade, reserva, venda, contrato ou financeiro.
create type public.subdivision_lot_inventory_phase as enum ('reference_confirmed','structure_review','review_required');
alter table public.subdivision_lots add constraint subdivision_lots_tenant_match unique (id, organization_id);
create table public.subdivision_lot_inventory_states (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, lot_id uuid not null, inventory_phase public.subdivision_lot_inventory_phase not null, created_by uuid not null references public.identity_subjects(user_id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint subdivision_lot_inventory_state_tenant_fk foreign key(lot_id,organization_id) references public.subdivision_lots(id,organization_id) on delete restrict, constraint subdivision_lot_inventory_state_unique unique(organization_id,lot_id));
alter table public.subdivision_lot_inventory_states enable row level security; revoke all on table public.subdivision_lot_inventory_states from public,anon,authenticated;
create or replace function public.subdivision_upsert_draft_lot_inventory_state(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_lot_id uuid,p_inventory_phase public.subdivision_lot_inventory_phase,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid; v_id uuid; begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); select target_id into v_existing from public.admin_audit_events where command_name='subdivision_upsert_draft_lot_inventory_state' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1; if v_existing is not null then return v_existing; end if; if not exists(select 1 from public.subdivision_lots where id=p_lot_id and organization_id=p_organization_id and state='draft') then raise exception using errcode='42501',message='SUBDIVISION_LOT_CONTEXT_DENIED'; end if; insert into public.subdivision_lot_inventory_states(organization_id,lot_id,inventory_phase,created_by) values(p_organization_id,p_lot_id,p_inventory_phase,p_actor_user_id) on conflict(organization_id,lot_id) do update set inventory_phase=excluded.inventory_phase,created_by=excluded.created_by,updated_at=now() returning id into v_id; insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted) values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_upsert_draft_lot_inventory_state','allowed','subdivision_lot_inventory_state',v_id,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'inventory_phase',p_inventory_phase::text)); return v_id; end; $$;
create or replace function public.subdivision_list_draft_lot_inventory_states(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(state_id uuid,lot_id uuid,inventory_phase public.subdivision_lot_inventory_phase,updated_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); return query select s.id,s.lot_id,s.inventory_phase,s.updated_at from public.subdivision_lot_inventory_states s join public.subdivision_lots l on l.id=s.lot_id and l.organization_id=s.organization_id where s.organization_id=p_organization_id and l.state='draft' order by s.updated_at desc; end; $$;
revoke all on function public.subdivision_upsert_draft_lot_inventory_state(uuid,uuid,public.operating_module,text,uuid,public.subdivision_lot_inventory_phase,uuid), public.subdivision_list_draft_lot_inventory_states(uuid,uuid,public.operating_module,text) from public,anon,authenticated; grant execute on function public.subdivision_upsert_draft_lot_inventory_state(uuid,uuid,public.operating_module,text,uuid,public.subdivision_lot_inventory_phase,uuid), public.subdivision_list_draft_lot_inventory_states(uuid,uuid,public.operating_module,text) to service_role;
